// This file is hand written and is not regenerated by `go generate
// ./internal/ent`: it is the controller heartbeat, the one set of writes in
// this package that the generated builders cannot express, because every one
// of them is stamped with the database server's clock rather than the
// caller's. See schema/controller_instance.go for why liveness is judged on
// that clock.
package ent

import (
	"context"
	stdsql "database/sql"
	"fmt"
	"strconv"
	"strings"
	"time"

	"entgo.io/ent/dialect"
	entsql "entgo.io/ent/dialect/sql"
)

// InstanceBeat describes the controller a heartbeat is for.
type InstanceBeat struct {
	// InstanceID is random per process start.
	InstanceID string

	// Version is the build's version.
	Version string

	// MigrationHead is the newest migration the build knows.
	MigrationHead string

	// Host names where the process runs.
	Host string
}

// Instance is one controller as its heartbeat last described it.
type Instance struct {
	InstanceID    string
	Version       string
	MigrationHead string
	Host          string

	// StartedUnix and LastSeenUnix are the database server's clock, in
	// seconds.
	StartedUnix  int64
	LastSeenUnix int64

	// SecondsSinceSeen is how long ago LastSeenUnix was, on the same clock.
	SecondsSinceSeen int64
}

// Heartbeat records that the described controller is alive now, by the
// database's clock, creating its row on the first beat.
//
// Update first, then insert: the row belongs to one process, so nothing
// else races its insert, and an update that finds the row is the ordinary
// case on every beat after the first.
func (c *Client) Heartbeat(ctx context.Context, beat InstanceBeat) error {
	db, dialectName, err := c.rawDB()
	if err != nil {
		return err
	}
	q, err := queriesFor(dialectName)
	if err != nil {
		return err
	}
	now := time.Now().UTC()
	res, err := db.ExecContext(ctx, q.update, now, beat.Version, beat.MigrationHead, beat.Host, beat.InstanceID)
	if err != nil {
		return fmt.Errorf("ent: recording a heartbeat: %w", err)
	}
	if n, err := res.RowsAffected(); err == nil && n > 0 {
		return nil
	}
	if _, err := db.ExecContext(ctx, q.insert, now, now, beat.InstanceID, beat.Version, beat.MigrationHead, beat.Host); err != nil {
		return fmt.Errorf("ent: recording the first heartbeat: %w", err)
	}
	return nil
}

// Deregister removes a controller's row, which a controller does as it shuts
// down cleanly so it stops counting as alive at once rather than after its
// heartbeats have aged out.
func (c *Client) Deregister(ctx context.Context, instanceID string) error {
	db, dialectName, err := c.rawDB()
	if err != nil {
		return err
	}
	if _, err := db.ExecContext(ctx, rebind(dialectName, `DELETE FROM controller_instances WHERE instance_id = ?`), instanceID); err != nil {
		return fmt.Errorf("ent: removing a controller's heartbeat: %w", err)
	}
	return nil
}

// Instances lists every controller with a heartbeat row, oldest start first,
// each with how long ago it was last seen.
func (c *Client) Instances(ctx context.Context) ([]Instance, error) {
	db, dialectName, err := c.rawDB()
	if err != nil {
		return nil, err
	}
	return listInstances(ctx, db, dialectName)
}

// listInstances reads every heartbeat row through db. It is shared by the
// live client and by ExistingDatabase, which reads a database without
// migrating it (controller migrate --plan).
func listInstances(ctx context.Context, db *stdsql.DB, dialectName string) ([]Instance, error) {
	q, err := queriesFor(dialectName)
	if err != nil {
		return nil, err
	}
	rows, err := db.QueryContext(ctx, q.list)
	if err != nil {
		return nil, fmt.Errorf("ent: reading controller heartbeats: %w", err)
	}
	defer func() { _ = rows.Close() }()
	var out []Instance
	for rows.Next() {
		var i Instance
		if err := rows.Scan(&i.InstanceID, &i.Version, &i.MigrationHead, &i.Host, &i.StartedUnix, &i.LastSeenUnix, &i.SecondsSinceSeen); err != nil {
			return nil, fmt.Errorf("ent: reading controller heartbeats: %w", err)
		}
		out = append(out, i)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("ent: reading controller heartbeats: %w", err)
	}
	return out, nil
}

// PruneInstances deletes rows not seen for longer than unseenFor, and says
// how many. Any controller may run it; two running it at once delete the same
// rows, which is harmless.
func (c *Client) PruneInstances(ctx context.Context, unseenFor time.Duration) (int64, error) {
	db, dialectName, err := c.rawDB()
	if err != nil {
		return 0, err
	}
	q, err := queriesFor(dialectName)
	if err != nil {
		return 0, err
	}
	res, err := db.ExecContext(ctx, q.prune, int64(unseenFor/time.Second))
	if err != nil {
		return 0, fmt.Errorf("ent: pruning controller heartbeats: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return 0, fmt.Errorf("ent: pruning controller heartbeats: %w", err)
	}
	return n, nil
}

// rawDB returns this client's own connection pool and dialect.
func (c *Client) rawDB() (*stdsql.DB, string, error) {
	drv, ok := c.driver.(*entsql.Driver)
	if !ok {
		return nil, "", fmt.Errorf("ent: this needs a SQL driver, not %T", c.driver)
	}
	return drv.DB(), drv.Dialect(), nil
}

// The database server's clock in whole Unix seconds, as a SQL expression, in
// each dialect. Constants, and every query below is assembled from them at
// compile time, so no statement this file sends is built from anything at run
// time but its bound parameters.
const (
	postgresNow = `CAST(EXTRACT(EPOCH FROM now()) AS BIGINT)`
	sqliteNow   = `CAST(strftime('%s', 'now') AS INTEGER)`
)

// instanceQueries is the heartbeat's statements in one dialect, written with
// "?" placeholders (rebind turns them into PostgreSQL's).
type instanceQueries struct {
	update, insert, list, prune string
}

// instanceSQL holds the heartbeat's statements for each dialect.
var instanceSQL = map[string]instanceQueries{
	dialect.Postgres: {
		update: `UPDATE controller_instances SET last_seen_unix = ` + postgresNow + `, updated_at = ?, version = ?, migration_head = ?, host = ? WHERE instance_id = ?`,
		insert: `INSERT INTO controller_instances (created_at, updated_at, instance_id, version, migration_head, host, started_unix, last_seen_unix) VALUES (?, ?, ?, ?, ?, ?, ` + postgresNow + `, ` + postgresNow + `)`,
		list:   `SELECT instance_id, version, migration_head, host, started_unix, last_seen_unix, ` + postgresNow + ` - last_seen_unix FROM controller_instances ORDER BY started_unix, instance_id`,
		prune:  `DELETE FROM controller_instances WHERE last_seen_unix < ` + postgresNow + ` - ?`,
	},
	dialect.SQLite: {
		update: `UPDATE controller_instances SET last_seen_unix = ` + sqliteNow + `, updated_at = ?, version = ?, migration_head = ?, host = ? WHERE instance_id = ?`,
		insert: `INSERT INTO controller_instances (created_at, updated_at, instance_id, version, migration_head, host, started_unix, last_seen_unix) VALUES (?, ?, ?, ?, ?, ?, ` + sqliteNow + `, ` + sqliteNow + `)`,
		list:   `SELECT instance_id, version, migration_head, host, started_unix, last_seen_unix, ` + sqliteNow + ` - last_seen_unix FROM controller_instances ORDER BY started_unix, instance_id`,
		prune:  `DELETE FROM controller_instances WHERE last_seen_unix < ` + sqliteNow + ` - ?`,
	},
}

// queriesFor returns the heartbeat's statements for a dialect, with
// placeholders already in that dialect's spelling.
func queriesFor(dialectName string) (instanceQueries, error) {
	q, ok := instanceSQL[dialectName]
	if !ok {
		return instanceQueries{}, fmt.Errorf("ent: no heartbeat statements for dialect %q", dialectName)
	}
	return instanceQueries{
		update: rebind(dialectName, q.update),
		insert: rebind(dialectName, q.insert),
		list:   q.list,
		prune:  rebind(dialectName, q.prune),
	}, nil
}

// rebind rewrites "?" placeholders as "$1", "$2", ... for PostgreSQL. The
// queries it is given are this file's own constants, none of which holds a
// "?" anywhere but a placeholder.
func rebind(dialectName, query string) string {
	if dialectName != dialect.Postgres {
		return query
	}
	var b strings.Builder
	n := 0
	for _, r := range query {
		if r == '?' {
			n++
			b.WriteString("$" + strconv.Itoa(n))
			continue
		}
		b.WriteRune(r)
	}
	return b.String()
}
